    indent = Pt(25.0)

    doc, s = create_document_base(font_size=font_size)
    body_width = s.page_width - s.left_margin - s.right_margin

    def add_p(text="", bold_prefix="", s_after=space_after, space_before=0, align=WD_ALIGN_PARAGRAPH.JUSTIFY, first_indent=indent, keep_with_next=False):
        p = doc.add_paragraph()
        p.paragraph_format.space_before = Pt(space_before)
        p.paragraph_format.space_after = Pt(s_after)
        p.paragraph_format.line_spacing = line_spacing
        p.paragraph_format.left_indent = Pt(0)
        p.paragraph_format.right_indent = Pt(0)
        p.alignment = align
        p.paragraph_format.first_line_indent = first_indent if first_indent is not None else Pt(0)
        if keep_with_next:
            p.paragraph_format.keep_with_next = True
        if bold_prefix:
            add_styled_run(p, bold_prefix, font_size=font_size, bold=True)
        if text:
            add_styled_run(p, text, font_size=font_size, bold=False)
        return p

    def add_h(text):
        p = doc.add_paragraph()
        p.paragraph_format.space_before = Pt(3.0)
        p.paragraph_format.space_after = Pt(1.5)
        p.paragraph_format.line_spacing = line_spacing
        p.alignment = WD_ALIGN_PARAGRAPH.CENTER
        p.paragraph_format.first_line_indent = Pt(0)
        p.paragraph_format.keep_with_next = True
        add_styled_run(p, text, font_size=font_size, bold=True)
        return p

